// FoundationStereo's cost-volume filtering (`corr_stem`, `corr_feature_att`, ...),
// against its own modules in FP64 (BatchNorm in eval mode, running statistics
// randomised). Fixtures generated by tests/fixtures/filtering/generate.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use teeny_core::name_scope::name_scope;
use vision_rs::models::stereo::filtering::{VOLUME_DIM, corr_stem, feature_att};

/// `corr_stem` (32 to 28 channels) then `corr_feature_att` with 24-channel features,
/// on a 6x5x7 volume.
#[test]
#[serial]
fn corr_stem_and_feature_att_match_pytorch() -> anyhow::Result<()> {
    check_block(
        "filtering/stem_att",
        "filtering/stem_att",
        &[("cv", &[1, 32, 6, 5, 7]), ("feat", &[1, 24, 5, 7])],
        |i| {
            let stem = {
                let _g = name_scope("corr_stem");
                corr_stem::<f32>(&i[0], 32, VOLUME_DIM)
            };
            let out = {
                let _g = name_scope("corr_feature_att");
                feature_att::<f32>(&stem, &i[1], VOLUME_DIM, 24)
            };
            vec![("stem", stem), ("", out)]
        },
        1e-4,
    )?;
    Ok(())
}
